style.css:
@-moz-document domain("youtube.com") {
/* ========== PALETA ========== */
  :root {
    --bg: #E6EEF4;
    --bg-card: #EDF3F7;
    --bg-elevated: #F0F5F8;
    --text: #1E3A4A;
    --text-sec: #5A7380;
    --accent: #7BA3B5;
    --accent-dark: #4A7A8C;
    --accent-hover: #6B9AAB;
    --border: #D5E3EC;
    --shadow: 0 4px 20px rgba(30, 58, 74, 0.07);
    --radius: 16px;
    --radius-sm: 12px;

    --yt-spec-base-background: var(--bg) !important;
    --yt-spec-raised-background: var(--bg-card) !important;
    --yt-spec-menu-background: var(--bg-elevated) !important;
    --yt-spec-text-primary: var(--text) !important;
    --yt-spec-text-secondary: var(--text-sec) !important;
    --yt-spec-text-primary-inverse: #ffffff !important;
    --yt-spec-brand-button-text: var(--text) !important;
    --yt-spec-static-brand-red: var(--accent) !important;
    --yt-spec-brand-red: var(--accent) !important;
    --yt-spec-call-to-action: var(--accent-hover) !important;
    --yt-spec-10-percent-layer: rgba(30, 58, 74, 0.06) !important;
    --yt-spec-badge-chip-background: var(--bg-elevated) !important;
    --yt-spec-button-chip-background-hover: rgba(123, 163, 181, 0.15) !important;
    --yt-spec-general-background-a: var(--bg) !important;
    --yt-spec-general-background-b: var(--bg-card) !important;
    --yt-spec-general-background-c: var(--bg-elevated) !important;
    --yt-spec-additive-background: rgba(30, 58, 74, 0.04) !important;
    --yt-spec-outline: var(--border) !important;
  }

  /* ========== FONDO GENERAL ========== */
  html, body, ytd-app, #content, ytd-page-manager, #page-manager {
    background-color: var(--bg) !important;
  }

  /* ========== LOGO COMPLETO ========== */
  /* Icono (rectángulo + triángulo) */
  ytd-topbar-logo-renderer #logo-icon,
  #logo-icon {
    filter: none !important;
  }

  /* Rectángulo → azul */
  ytd-topbar-logo-renderer #logo-icon path:first-child,
  #logo-icon path:first-child,
  ytd-topbar-logo-renderer #logo-icon path[fill*="FF0000"],
  ytd-topbar-logo-renderer #logo-icon path[fill*="f00"],
  ytd-topbar-logo-renderer #logo-icon path[fill*="red"] {
    fill: var(--accent) !important;
  }

  /* Triángulo → blanco */
  ytd-topbar-logo-renderer #logo-icon path:last-child,
  #logo-icon path:last-child,
  ytd-topbar-logo-renderer #logo-icon path[fill*="FFF"],
  ytd-topbar-logo-renderer #logo-icon path[fill*="fff"],
  ytd-topbar-logo-renderer #logo-icon path[fill*="white"] {
    fill: #ffffff !important;
  }

  /* Letras “YouTube” → azul */
  ytd-topbar-logo-renderer,
  ytd-topbar-logo-renderer a,
  ytd-topbar-logo-renderer #logo-text,
  ytd-topbar-logo-renderer yt-formatted-string,
  #logo-text,
  ytd-logo {
    color: var(--accent) !important;
  }

  /* Country code (PE) también en azul */
  #country-code {
    color: var(--accent) !important;
  }

  /* ========== HEADER ========== */
  ytd-masthead,
  #masthead-container,
  #background.ytd-masthead,
  #container.ytd-masthead {
    background-color: var(--bg-card) !important;
    background: var(--bg-card) !important;
    border-bottom: 1px solid var(--border) !important;
    box-shadow: var(--shadow) !important;
  }

  ytd-searchbox #container, 
  ytd-searchbox #search-input {
    background-color: var(--bg-elevated) !important;
    border: 1px solid var(--border) !important;
    border-radius: 24px !important;
    color: var(--text) !important;
  }

  ytd-searchbox #search-icon-legacy {
    background-color: var(--accent) !important;
    border-radius: 0 24px 24px 0 !important;
  }

  /* ========== LÍNEAS BLANCAS ========== */
  ytd-feed-filter-chip-bar-renderer,
  #chips-wrapper,
  #header.ytd-rich-grid-renderer,
  ytd-rich-grid-renderer > #header,
  ytd-browse #header {
    border: none !important;
    border-bottom: none !important;
    box-shadow: none !important;
    background-color: var(--bg) !important;
  }

  ytd-feed-filter-chip-bar-renderer::before,
  ytd-feed-filter-chip-bar-renderer::after,
  #chips-wrapper::before,
  #chips-wrapper::after {
    display: none !important;
    content: none !important;
  }

  /* ========== SIDEBAR ========== */
  #guide-content, ytd-mini-guide-renderer, 
  ytd-guide-renderer, tp-yt-app-drawer {
    background-color: var(--bg-card) !important;
    border-right: 1px solid var(--border) !important;
  }

  ytd-guide-section-renderer #guide-section-title,
  #guide-section-title,
  yt-formatted-string#guide-section-title {
    color: var(--accent-dark) !important;
    font-weight: 600 !important;
  }

  ytd-guide-entry-renderer yt-formatted-string,
  ytd-mini-guide-entry-renderer yt-formatted-string {
    color: var(--text) !important;
  }

  ytd-guide-entry-renderer:hover,
  ytd-mini-guide-entry-renderer:hover {
    background-color: rgba(123, 163, 181, 0.12) !important;
    border-radius: 12px !important;
  }

  ytd-guide-entry-renderer[active],
  ytd-mini-guide-entry-renderer[active] {
    background-color: rgba(123, 163, 181, 0.18) !important;
  }

  /* ========== TÍTULOS DE VIDEOS EN AZUL ========== */
  #video-title,
  ytd-video-renderer #video-title,
  ytd-rich-item-renderer #video-title,
  ytd-grid-video-renderer #video-title,
  ytd-compact-video-renderer #video-title,
  a#video-title,
  yt-formatted-string#video-title {
    color: var(--accent-dark) !important;
    font-weight: 500 !important;
  }

  /* Metadata un poco más suave */
  #metadata-line,
  .ytd-video-meta-block,
  #channel-name {
    color: var(--text-sec) !important;
  }

  /* ========== LIKE / DISLIKE ========== */
  ytd-toggle-button-renderer yt-icon,
  #like-button yt-icon,
  #dislike-button yt-icon,
  ytd-segmented-like-dislike-button-renderer yt-icon {
    color: var(--accent) !important;
  }

  /* Cuando está activo (likeado) */
  ytd-toggle-button-renderer[is-active] yt-icon,
  #like-button[aria-pressed="true"] yt-icon {
    color: var(--accent-dark) !important;
  }

  /* Texto de likes */
  ytd-toggle-button-renderer yt-formatted-string,
  #like-button yt-formatted-string {
    color: var(--accent-dark) !important;
  }

  /* ========== GRID ========== */
  ytd-rich-grid-renderer {
    --ytd-rich-grid-items-per-row: 3 !important;
  }

  ytd-rich-item-renderer {
    max-width: 380px !important;
  }

  /* ========== TARJETAS ========== */
  ytd-rich-item-renderer, 
  ytd-video-renderer, 
  ytd-grid-video-renderer,
  ytd-compact-video-renderer {
    background-color: var(--bg-card) !important;
    border-radius: var(--radius) !important;
    overflow: hidden;
    box-shadow: var(--shadow);
    border: 1px solid transparent;
    transition: all 0.25s ease;
  }

  ytd-rich-item-renderer:hover, 
  ytd-video-renderer:hover {
    border-color: var(--border);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(30, 58, 74, 0.1);
  }

  ytd-thumbnail, #thumbnail, .yt-core-image {
    border-radius: var(--radius-sm) !important;
  }

  /* ========== BARRA DE PROGRESO ========== */
  .ytp-play-progress {
    background: var(--accent) !important;
  }

  .ytp-load-progress {
    background: rgba(123, 163, 181, 0.35) !important;
  }

  .ytp-scrubber-button,
  .ytp-scrubber-button:hover {
    background: var(--accent) !important;
    border-color: var(--accent) !important;
  }

  .ytp-swatch-background-color,
  .ytp-swatch-color {
    background-color: var(--accent) !important;
  }

  /* ========== BOTÓN SUSCRIBIRSE ========== */
  ytd-subscribe-button-renderer yt-button-shape button,
  ytd-subscribe-button-renderer .yt-spec-button-shape-next,
  #subscribe-button yt-button-shape button {
    background-color: var(--accent) !important;
    color: white !important;
    border-radius: 22px !important;
    border: none !important;
    padding: 0 18px !important;
    font-weight: 500 !important;
  }

  ytd-subscribe-button-renderer yt-button-shape button:hover {
    background-color: var(--accent-hover) !important;
  }

  ytd-subscribe-button-renderer[subscribed] yt-button-shape button {
    background-color: var(--bg-elevated) !important;
    color: var(--text) !important;
    border: 1px solid var(--border) !important;
  }

  /* ========== PÁGINA DE VIDEO ========== */
  ytd-watch-flexy {
    background-color: var(--bg) !important;
  }

  ytd-compact-video-renderer {
    background-color: var(--bg-card) !important;
    border-radius: var(--radius-sm) !important;
    margin-bottom: 8px !important;
    padding: 6px !important;
  }

  ytd-video-secondary-info-renderer,
  ytd-comments, #comments {
    background-color: var(--bg-card) !important;
    border-radius: var(--radius) !important;
    padding: 16px !important;
    border: 1px solid var(--border) !important;
  }

  /* ========== BOTONES Y CHIPS ========== */
  ytd-button-renderer, yt-button-shape button,
  .yt-spec-button-shape-next {
    border-radius: 20px !important;
  }

  yt-chip-cloud-chip-renderer {
    background-color: var(--bg-elevated) !important;
    border: 1px solid var(--border) !important;
    color: var(--text) !important;
    border-radius: 20px !important;
  }

  yt-chip-cloud-chip-renderer[selected] {
    background-color: var(--accent) !important;
    color: white !important;
    border-color: var(--accent) !important;
  }

  /* ========== MENÚS ========== */
  tp-yt-paper-listbox,
  ytd-menu-popup-renderer {
    background-color: var(--bg-elevated) !important;
    border: 1px solid var(--border) !important;
    border-radius: var(--radius-sm) !important;
    box-shadow: var(--shadow) !important;
  }

  /* ========== SCROLLBAR ========== */
  ::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }
  ::-webkit-scrollbar-track {
    background: var(--bg);
  }
  ::-webkit-scrollbar-thumb {
    background: var(--accent);
    border-radius: 4px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: var(--accent-hover);
  }

  #masthead-ad,
  ytd-ad-slot-renderer,
  ytd-banner-promo-renderer {
    display: none !important;
  }
}
